+.search-close-button {
+  position: absolute;
+  right: 0; top: 50%;
+  display: flex;
+  align-items: center;
+  padding: 5px;
+  margin: 0;
+  border: 0;
+  background: transparent;
+  color: var(--searchAccentMain);
+  font-size: var(--text-md);
+  cursor: pointer;
+  opacity: .5;
+  transform: translateY(-50%) scaleY(0);
+  transition: var(--transition-all);
+}
+.search-close-button:hover { opacity: .7; }
+.search-close-button svg { width: 1.25em; height: 1.25em; }
+.search-bar.has-value .search-close-button { transform: translateY(-50%) scaleY(1); }
+
+.icon-settings {
+  display: flex;
+  align-items: center;
+  justify-content: flex-end;
+  padding: 0;
+  border: 0;
+  background: transparent;
+  color: var(--iconAction);
+  font-size: var(--text-xl);
