+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  color: var(--sidebarSubheadings);
+}
+
+.full-list li[hidden] { display: none; }
+
+.full-list li > a {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  padding: 5px 20px 5px 30px;
+  font-size: var(--text-sm);
+  line-height: 1.4;
